function Pixels({ id }: { id: string }) {
  return (
    <svg viewBox="0 0 400 240" role="img" aria-label={`Pixel art drawing of a ${labels[id]}`} shapeRendering="crispEdges">
      {sprites[id].flatMap((row, y) =>
        [...row.matchAll(/([^.])\1*/g)].map((m) => (
          <rect
            key={`${y}-${m.index}`}
            x={m.index * 10}
            y={y * 10}
            width={m[0].length * 10}
            height={10}
            fill={palette[m[0][0]]}
          />
        )),
      )}
    </svg>
  );
}

export const pixelArt: Record<string, () => ReactNode> = Object.fromEntries(
  Object.keys(sprites).map((id) => [id, () => <Pixels id={id} />]),
);
